const fs = require('fs');
const path = require('path');

// ============================================================
// generar_475_seis_arreglos.js
// ============================================================
// Los seis problemas que encontro Casandra usando el chat.
//
// 1. LOS VIAJES NO SE RECONOCIAN
//    Mis frases eran literales: 'me voy de viaje', 'salir de viaje'.
//    "voy a viajar" no calzaba con ninguna. Ahora son raices ('viaj')
//    y la pregunta ambigua se activa con frases cortas, no solo con una
//    palabra suelta:
//
//      Tú: voy a viajar
//      Chiqui: ¿Viajas con él, o se queda en casa?
//              [Viajo con él en auto] [Se queda en casa]
//
// 2. "ESTADO REPRODUCTIVO" NO SE ENTENDIA
//    La frase completa no estaba en las intenciones del perfil.
//
// 3. "DESCONOCIDO" COMO RESPUESTA
//    Es un valor real en la base, pero como respuesta no sirve: es lo
//    mismo que no tener el dato. Ahora dice donde anotarlo.
//
// 4. OBSERVACIONES Y MOMENTOS respondian el manual en vez de los datos
//    Faltaba la intencion: cualquier pregunta caia en "¿donde guardo
//    una observacion?" en vez de contar las registradas. Ahora se
//    separan las que estan en seguimiento de las ya resueltas.
//
// 5. LOS ANTIPARASITARIOS NO OFRECIAN VER LOS ANTERIORES
//    El boton salia de la lista vigente, que en antiparasitarios es de
//    UNO solo. Ahora sale del historial:
//
//      · Simparica — en 18 días (10 sep)
//      Antes le diste 1 dosis más.
//      [¿Qué antiparasitarios le he dado?]
//
// 6. "¿QUE FRUTAS PUEDE COMER?" NO TENIA RESPUESTA
//    Es una de las sugerencias del propio menu y caia en "no estoy
//    seguro", porque buscaba un alimento concreto y no encontraba
//    ninguno. Ahora hay una respuesta completa, con su contraria:
//
//      Tú: ¿qué frutas puede comer?
//      Chiqui: Manzana y pera sin semillas, sandía y melón sin
//              cáscara, plátano en poca cantidad, arándanos,
//              zanahoria cruda...
//              [¿Qué NO puede comer?]
//
// REQUISITO: script 473 desplegado.
//
// Si algo no calza, ABORTA sin escribir NADA.
// ============================================================

const RUTA_CHAT = 'components/ChiquiChat.tsx';
const RUTA_FLOT = 'components/ChiquiFlotante.tsx';
const CHAT_B64 = '';
const FLOT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico NINGUN archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const dChat = path.join(process.cwd(), RUTA_CHAT);
const dFlot = path.join(process.cwd(), RUTA_FLOT);
for (const [r, d] of [[RUTA_CHAT, dChat], [RUTA_FLOT, dFlot]]) {
  if (!fs.existsSync(d)) abortar('no se encontro ' + r + '.');
}

const actual = fs.readFileSync(dChat, 'utf8');
if (actual.includes("case 'observaciones'")) {
  abortar('el chat ya tiene esto. Parece que este script ya se corrio.');
}
if (!actual.includes('function calcularEdad')) {
  abortar('falta el script 473. Correlo primero.');
}

const chat = Buffer.from(CHAT_B64, 'base64').toString('utf8');
const flot = Buffer.from(FLOT_B64, 'base64').toString('utf8');

for (const r of ["case 'observaciones'", 'Frutas y verduras que sí puede comer',
                 'Antes le diste', 'No tengo anotado si', 'palabrasQ.length <= 4']) {
  if (!chat.includes(r)) abortar('el chat nuevo no incluye [' + r + ']. Script corrupto.');
}
console.log('  OK  los 6 arreglos estan en el chat');

// El bloque de frutas TIENE que ir antes del generico de alimentos, o
// nunca se alcanza.
const posFrutas = chat.indexOf('Frutas y verduras que sí puede comer');
const posGenerico = chat.indexOf('De ese no estoy seguro');
if (posFrutas > posGenerico) {
  abortar('el bloque de frutas quedaria despues del generico: nunca se alcanzaria.');
}
console.log('  OK  las frutas se responden antes del generico');

if (!flot.includes("from('observaciones')")) {
  abortar('el flotante no trae las observaciones. Script corrupto.');
}
console.log('  OK  el flotante trae las observaciones');

fs.writeFileSync(dChat, chat, 'utf8');
console.log('');
console.log('OK: ' + RUTA_CHAT);
fs.writeFileSync(dFlot, flot, 'utf8');
console.log('OK: ' + RUTA_FLOT);
console.log('');
console.log('Prueba: "voy a viajar", "que frutas puede comer", "que');
console.log('observaciones tiene" y "estado reproductivo".');
console.log('');
console.log('Listo.');
